#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const HEADER =
  '<!-- AUTO-GENERATED by polotno-ai-rules from rules/polotno-rules.md — DO NOT EDIT -->\n\n';

const PLATFORMS = {
  cursor: { file: '.cursorrules', description: 'Cursor' },
  copilot: {
    file: '.github/copilot-instructions.md',
    description: 'GitHub Copilot',
  },
  codex: { file: 'AGENTS.md', description: 'Codex / Jules / Aider' },
  windsurf: { file: '.windsurfrules', description: 'Windsurf' },
};

function printHelp() {
  console.log(`
  polotno-ai-rules — Set up Polotno SDK AI coding rules for your project

  Usage:
    npx polotno-ai-rules [options]

  Options:
    --cursor      Set up for Cursor (.cursorrules)
    --copilot     Set up for GitHub Copilot (.github/copilot-instructions.md)
    --codex       Set up for Codex / Jules / Aider (AGENTS.md)
    --windsurf    Set up for Windsurf (.windsurfrules)
    --all         Set up for all platforms
    --mcp         Also copy .mcp.json for MCP-compatible editors (Cursor, Claude Code)
    --help        Show this help message

  Examples:
    npx polotno-ai-rules --all
    npx polotno-ai-rules --cursor --mcp
    npx polotno-ai-rules --copilot --codex

  For Claude Code, install the plugin instead:
    claude plugin add polotno-project/polotno-ai-rules
`);
}

function readSource() {
  const src = path.join(__dirname, '..', 'rules', 'polotno-rules.md');
  if (!fs.existsSync(src)) {
    console.error('  ✗ Source file not found: rules/polotno-rules.md');
    process.exit(1);
  }
  return fs.readFileSync(src, 'utf-8');
}

function writeRules(content, destRelative, destDir) {
  const dest = path.join(destDir, destRelative);
  const destDirPath = path.dirname(dest);
  if (!fs.existsSync(destDirPath)) {
    fs.mkdirSync(destDirPath, { recursive: true });
  }
  fs.writeFileSync(dest, HEADER + content);
  console.log(`  ✓ ${destRelative}`);
  return true;
}

function mergeMcpConfig(destDir) {
  const src = path.join(__dirname, '..', '.mcp.json');
  const dest = path.join(destDir, '.mcp.json');

  if (!fs.existsSync(src)) {
    console.error('  ✗ Source .mcp.json not found');
    return false;
  }

  const srcConfig = JSON.parse(fs.readFileSync(src, 'utf-8'));

  if (fs.existsSync(dest)) {
    try {
      const existingConfig = JSON.parse(fs.readFileSync(dest, 'utf-8'));
      existingConfig.mcpServers = existingConfig.mcpServers || {};
      Object.assign(existingConfig.mcpServers, srcConfig.mcpServers);
      fs.writeFileSync(dest, JSON.stringify(existingConfig, null, 2) + '\n');
      console.log('  ✓ .mcp.json (merged with existing)');
    } catch {
      fs.copyFileSync(src, dest);
      console.log('  ✓ .mcp.json (replaced invalid existing file)');
    }
  } else {
    fs.copyFileSync(src, dest);
    console.log('  ✓ .mcp.json');
  }
  return true;
}

function main() {
  const args = process.argv.slice(2);

  if (args.length === 0 || args.includes('--help')) {
    printHelp();
    process.exit(0);
  }

  const destDir = process.cwd();
  const doAll = args.includes('--all');
  const doMcp = args.includes('--mcp') || doAll;

  const selectedPlatforms = doAll
    ? Object.keys(PLATFORMS)
    : Object.keys(PLATFORMS).filter((p) => args.includes(`--${p}`));

  if (selectedPlatforms.length === 0 && !doMcp) {
    console.error(
      'No platforms selected. Use --all or specify platforms (--cursor, --copilot, --codex, --windsurf).'
    );
    process.exit(1);
  }

  console.log('\nPolotno SDK AI Rules Setup\n');

  const source = readSource();

  let copied = 0;
  for (const platform of selectedPlatforms) {
    const { file, description } = PLATFORMS[platform];
    console.log(`Setting up ${description}...`);
    if (writeRules(source, file, destDir)) {
      copied++;
    }
  }

  if (doMcp) {
    console.log('\nSetting up MCP server config...');
    if (mergeMcpConfig(destDir)) {
      copied++;
    }
  }

  console.log(`\nDone! ${copied} file(s) written to ${destDir}`);

  console.log('\nNext steps:');
  if (
    selectedPlatforms.includes('cursor') ||
    selectedPlatforms.includes('copilot')
  ) {
    console.log('  • Restart your editor to pick up the new rules');
  }
  if (doMcp) {
    console.log(
      '  • MCP server will start automatically when your editor reads .mcp.json'
    );
  }
  console.log('  • Full docs: https://polotno.com/docs');
  console.log(
    '  • For Claude Code: claude plugin add polotno-project/polotno-ai-rules\n'
  );
}

main();
